from fastapi import FastAPI, HTTPException, Path
from fastapi.responses import RedirectResponse
from pydantic import BaseModel
from typing import Dict, Optional

app = FastAPI()

class ShortenRequest(BaseModel):
    long_url: str

class ShortenResponse(BaseModel):
    short_code: str

class StatsResponse(BaseModel):
    clicks: int

class HealthResponse(BaseModel):
    status: str

# In-memory storage
url_storage: Dict[str, str] = {}
clicks_storage: Dict[str, int] = {}

@app.post("/shorten", response_model=ShortenResponse)
def shorten(request: ShortenRequest):
    short_code = str(len(url_storage) + 1)  # Simple short code generation
    url_storage[short_code] = request.long_url
    clicks_storage[short_code] = 0
    return ShortenResponse(short_code=short_code)

@app.get("/{short_code}", response_class=RedirectResponse, status_code=307)
def redirect_to_long_url(short_code: str = Path(...)):
    long_url = url_storage.get(short_code)
    if long_url:
        clicks_storage[short_code] += 1
        return RedirectResponse(url=long_url)
    raise HTTPException(status_code=404)

@app.get("/{short_code}", response_model=None, status_code=404)
def not_found(short_code: str = Path(...)):
    raise HTTPException(status_code=404)

@app.get("/stats/{short_code}", response_model=StatsResponse)
def get_stats(short_code: str = Path(...)):
    clicks = clicks_storage.get(short_code)
    if clicks is not None:
        return StatsResponse(clicks=clicks)
    raise HTTPException(status_code=404)

@app.get("/stats/{short_code}", response_model=None, status_code=404)
def not_found_stats(short_code: str = Path(...)):
    raise HTTPException(status_code=404)

@app.get("/health", response_model=HealthResponse, status_code=200)
def health_check():
    return HealthResponse(status="ok")

@app.get("/health", response_model=HealthResponse, status_code=503)
def health_check_unavailable():
    raise HTTPException(status_code=503, detail="Service Unavailable")
